const BY_BEAT = []
for (const h of HARMONY) for (let b = h[0]; b < h[0] + h[1]; b++) BY_BEAT[b] = h
const chordAt = x => BY_BEAT[floor(x)] ?? null
const padOn = x => chordAt(x) && ['themeB', 'bridge', 'break', 'final', 'intro'].includes(role(x)) && x < END - 2 // pads play here
const SCALE = [2, 4, 5, 7, 9, 10, 0] // D минор, pitch classes from C

// ---- the fight: the kick, the sidechain, the key changes --------------------------------------------------------
const SEC = 60 / 148 // seconds per beat
const sectionEnd = x => ROLE.find(r => r[0] > x)?.[0] ?? END
const KEY_UP = [] // [start, semitones up]
const trAt = x => { let t = 0; for (const [s, k] of KEY_UP) if (s <= x) t = k; return t }
const TONIC1 = 38 // MIDI: the tonic in octave 1 — the kick's tail and the reverse bass sit on it
const KICK_GAIN = 0.9701 // a higher tail carries more energy: (46 Hz / f)^1.2
// the kick: every beat of the intro and the outro, every beat in a drop; in a build-up it comes in halfway and doubles
// (1, ½, ¼ beat); one last hit to close  → { τ beats since the hit, vel, g the grid }
const kickAt = x => {
  if (x < 0 || x >= END) return null
  const [s, r, e] = sectionOf(x), t = x - s, L = sectionEnd(x) - s
  if (r === 'intro') return { τ: mod(t, 1), vel: 0.85 + (0.1 * t) / L, g: 1 } // the DJ intro: four on the floor from the first beat
  if (r === 'outro') return t < L - 4 ? { τ: mod(t, 1), vel: 0.95, g: 1 } : { τ: t - L + 4, vel: 1, g: 4 } // the DJ outro, one last hit
  const g = e >= 3 ? 1 : r === 'build' ? (t < L / 2 ? 0 : t < 0.75 * L ? 1 : t < 0.875 * L ? 0.5 : 0.25) : 0
  return g ? { τ: mod(t, g), vel: r === 'build' ? 0.55 + (0.4 * t) / L : 1, g } : null
}
// the sidechain: in a drop every part dips under the kick and comes back in 0.18 s
const pumpAt = x => { const k = kickAt(x); return k && energy(x) >= 3 ? duck(k.τ * SEC) : 1 }

